<?php
namespace App\Services;
use App\Models\{Parcel,ShipmentEvent,SortingCenter,Waybill}; use App\Models\User; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class ParcelIntakeService { public function receive(Waybill $waybill,SortingCenter $center,User $actor,string $method='camera'):Waybill{return DB::transaction(function()use($waybill,$center,$actor,$method){$waybill=Waybill::query()->lockForUpdate()->with(['shipment.sellerOrder.store','parcels'])->findOrFail($waybill->id);foreach($waybill->parcels as $parcel){if(in_array($parcel->status,['received_at_center','awaiting_sort','sorted','loaded','out_for_delivery','delivered'],true))throw ValidationException::withMessages(['waybill'=>'This parcel was already received.']);$from=$parcel->status;$parcel->update(['status'=>'received_at_center','current_sorting_center_id'=>$center->id,'last_event_at'=>now()]);ShipmentEvent::create(['shipment_id'=>$waybill->shipment_id,'parcel_id'=>$parcel->id,'event_type'=>'received_at_center','from_status'=>$from,'to_status'=>'received_at_center','sorting_center_id'=>$center->id,'actor_user_id'=>$actor->id,'source'=>'scan','scan_method'=>$method,'occurred_at'=>now()]);}$waybill->shipment->update(['status'=>'at_sorting_center']);return $waybill->fresh(['shipment.sellerOrder.store','parcels']);});} }
